import React, { useState } from 'react';
import { useNavigate } from 'react-router-dom';
import { createListing } from '../../services/carListingService';
import toast from 'react-hot-toast';

const CreateListing = () => {
  const navigate = useNavigate();
  const [formData, setFormData] = useState({
    brand: '',
    model: '',
    year: new Date().getFullYear(),
    mileage: '',
    condition: 'good',
    exterior: '',
    interior: '',
    engine: '',
    desiredPrice: '',
    notes: '',
  });
  const [loading, setLoading] = useState(false);

  const handleChange = (e) => {
    setFormData({ ...formData, [e.target.name]: e.target.value });
  };

  const handleSubmit = async (e) => {
    e.preventDefault();
    setLoading(true);
    try {
      await createListing({
        ...formData,
        year: parseInt(formData.year),
        mileage: parseInt(formData.mileage),
        desiredPrice: parseInt(formData.desiredPrice),
      });
      toast.success('Đã gửi yêu cầu bán xe');
      navigate('/customer/dashboard');
    } catch (err) {
      toast.error(err.response?.data?.message || 'Có lỗi xảy ra');
    } finally {
      setLoading(false);
    }
  };

  return (
    <div className="max-w-3xl mx-auto p-6">
      <h2 className="text-2xl font-bold mb-6">Đăng bán xe cũ</h2>
      <form onSubmit={handleSubmit} className="space-y-4">
        <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
          <div>
            <label className="block mb-1 font-medium">Hãng xe *</label>
            <input
              type="text"
              name="brand"
              value={formData.brand}
              onChange={handleChange}
              required
              className="w-full border rounded p-2"
              placeholder="Ví dụ: Toyota, Honda, Ford"
            />
          </div>
          <div>
            <label className="block mb-1 font-medium">Phiên bản *</label>
            <input
              type="text"
              name="model"
              value={formData.model}
              onChange={handleChange}
              required
              className="w-full border rounded p-2"
              placeholder="Ví dụ: Camry, Civic, Ranger"
            />
          </div>
          <div>
            <label className="block mb-1 font-medium">Năm sản xuất *</label>
            <input
              type="number"
              name="year"
              value={formData.year}
              onChange={handleChange}
              required
              min="1980"
              max={new Date().getFullYear()}
              className="w-full border rounded p-2"
            />
          </div>
          <div>
            <label className="block mb-1 font-medium">Số km đã đi *</label>
            <input
              type="number"
              name="mileage"
              value={formData.mileage}
              onChange={handleChange}
              required
              className="w-full border rounded p-2"
              placeholder="km"
            />
          </div>
          <div>
            <label className="block mb-1 font-medium">Tình trạng tổng thể</label>
            <select
              name="condition"
              value={formData.condition}
              onChange={handleChange}
              className="w-full border rounded p-2"
            >
              <option value="excellent">Tuyệt vời</option>
              <option value="good">Tốt</option>
              <option value="fair">Trung bình</option>
              <option value="poor">Kém</option>
            </select>
          </div>
          <div>
            <label className="block mb-1 font-medium">Giá mong muốn (VND) *</label>
            <input
              type="number"
              name="desiredPrice"
              value={formData.desiredPrice}
              onChange={handleChange}
              required
              className="w-full border rounded p-2"
              placeholder="Ví dụ: 300000000"
            />
          </div>
        </div>
        <div>
          <label className="block mb-1 font-medium">Ngoại thất</label>
          <textarea
            name="exterior"
            value={formData.exterior}
            onChange={handleChange}
            rows="2"
            className="w-full border rounded p-2"
            placeholder="Mô tả trầy xước, móp, sơn..."
          />
        </div>
        <div>
          <label className="block mb-1 font-medium">Nội thất</label>
          <textarea
            name="interior"
            value={formData.interior}
            onChange={handleChange}
            rows="2"
            className="w-full border rounded p-2"
            placeholder="Tình trạng ghế, taplo, điều hòa..."
          />
        </div>
        <div>
          <label className="block mb-1 font-medium">Động cơ & hộp số</label>
          <textarea
            name="engine"
            value={formData.engine}
            onChange={handleChange}
            rows="2"
            className="w-full border rounded p-2"
            placeholder="Có tiếng kêu lạ, khói, hao dầu không?"
          />
        </div>
        <div>
          <label className="block mb-1 font-medium">Ghi chú thêm</label>
          <textarea
            name="notes"
            value={formData.notes}
            onChange={handleChange}
            rows="2"
            className="w-full border rounded p-2"
          />
        </div>
        <div className="flex space-x-3">
          <button
            type="submit"
            disabled={loading}
            className="bg-blue-600 text-white px-6 py-2 rounded hover:bg-blue-700 disabled:opacity-50"
          >
            {loading ? 'Đang gửi...' : 'Gửi yêu cầu'}
          </button>
          <button
            type="button"
            onClick={() => navigate('/customer/dashboard')}
            className="bg-gray-300 px-6 py-2 rounded hover:bg-gray-400"
          >
            Hủy
          </button>
        </div>
      </form>
    </div>
  );
};

export default CreateListing;
